int choix = 0;
do
{
    cout << "1-Nourrir 2-Jouer 0-Quitter : ";
    cin >> choix;
    switch (choix)
    {
        case 1:
        {
            cout << "Miam!\n";
        }
        break;
        case 2:
        {
            cout << "Pelote!\n";
        }
        break;
        case 0:
        {
            cout << "Bye!\n";
        }
        break;
        default:
        {
            cout << "Choix invalide\n";
        }
        break;
    }
} while (choix != 0);

int choix = 0;
do
{
    cout << "[Principal] 1-Jeux 0-Quitter : ";
    cin >> choix;
    switch (choix)
    {
        case 1:
        {
            int sousChoix = 0;
            do
            {
                cout << "[Jeux] 1-Laser 0-Retour : ";
                cin >> sousChoix;
                if (sousChoix == 1)
                {
                    cout << "Chasse au laser!\n";
                }
            } while (sousChoix != 0);
        }
        break;
        case 0:
        {
            cout << "Bye!\n";
        }
        break;
        default:
        {
            cout << "Invalide\n";
        }
        break;
    }
} while (choix != 0);

